#include "edgemap.h"

#include <stdlib.h>
#include <string.h>

struct EdgeMap {
    int edge_levels;
    double edge_threshold;
    char *charset;      /* owned, NUL-terminated copy */
    size_t charset_len;  /* strlen(charset), always >= 1 */
    char *glyph_lut;     /* owned, length edge_levels: glyph_lut[level] */
