    char line[128];

    for (size_t i = 0; i < track.count; i++) {
        render_frame(map, i, track.values[i]);

        while (stdin_line_ready()) {
            if (!fgets(line, sizeof(line), stdin)) break;
            handle_command(line, map);
        }

        if (frame_delay) usleep(frame_delay);
    }

    edgemap_destroy(map);
    envelope_free(&track);
    return 0;
}

